// GENERADO a partir de los datos CLDR de ICU (macOS libicucore).
// Países ISO 3166-1 con su código alfa-3 y su nombre en los idiomas de la app.
// No editar a mano: regenerar si hace falta.

/// País ISO 3166-1 (código alfa-3, el que guarda el registro de viajeros)
class Country {
  const Country(this.alpha3, this._names);

  final String alpha3;
  final Map<String, String> _names;

  /// Nombre en el idioma indicado (código de idioma: es, en, de…).
  /// Si no existe, en inglés.
  String nameFor(String languageCode) =>
      _names[languageCode] ?? _names['en'] ?? alpha3;

  /// Todos los nombres, para buscar en cualquier idioma
  Iterable<String> get allNames => _names.values;
}

/// Busca un país por su código alfa-3
Country? countryByAlpha3(String? alpha3) {
  if (alpha3 == null) return null;
  for (final country in kCountries) {
    if (country.alpha3 == alpha3) return country;
  }
  return null;
}

